$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$out = $PSScriptRoot
$root = (Resolve-Path "$out/../../..").Path
$code = @'
using System;
using System.IO;
using System.Drawing;
using System.Drawing.Imaging;
using System.Drawing.Drawing2D;
using System.Collections.Generic;
public static class TutorialArt {
 public static string Out;
 public static Color Ink=ColorTranslator.FromHtml("#211e26"), Brass=ColorTranslator.FromHtml("#ba873f"), Light=ColorTranslator.FromHtml("#e2bd68"), Rust=ColorTranslator.FromHtml("#725036"), Paper=ColorTranslator.FromHtml("#c7ad70"), Pale=ColorTranslator.FromHtml("#dcc58d"), Dark=ColorTranslator.FromHtml("#51483d"), Steel=ColorTranslator.FromHtml("#8f9187"), Red=ColorTranslator.FromHtml("#874739"), Green=ColorTranslator.FromHtml("#66835d");
 public static Bitmap New(int w,int h){return new Bitmap(w,h,PixelFormat.Format32bppArgb);}
 public static void Rect(Bitmap b,int x,int y,int w,int h,Color c){using(Graphics g=Graphics.FromImage(b))using(Brush p=new SolidBrush(c)){g.CompositingMode=CompositingMode.SourceCopy;g.FillRectangle(p,x,y,w,h);}}
 public static void Poly(Bitmap b,Color c,params int[] xy){Point[] ps=new Point[xy.Length/2];for(int i=0;i<ps.Length;i++)ps[i]=new Point(xy[2*i],xy[2*i+1]);using(Graphics g=Graphics.FromImage(b))using(Brush p=new SolidBrush(c)){g.FillPolygon(p,ps);}}
 public static void Line(Bitmap b,Color c,int width,params int[] xy){Point[] ps=new Point[xy.Length/2];for(int i=0;i<ps.Length;i++)ps[i]=new Point(xy[2*i],xy[2*i+1]);using(Graphics g=Graphics.FromImage(b))using(Pen p=new Pen(c,width)){g.SmoothingMode=SmoothingMode.None;g.DrawLines(p,ps);}}
 public static Bitmap Scale(Bitmap b,int n){Bitmap r=New(b.Width*n,b.Height*n);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){Color c=b.GetPixel(x,y);if(c.A>0)Rect(r,x*n,y*n,n,n,c);}return r;}
 public static void Paste(Bitmap b,Bitmap src,int x,int y){using(Graphics g=Graphics.FromImage(b)){g.DrawImageUnscaled(src,x,y);}}
 public static void Save(Bitmap b,string name){b.Save(Path.Combine(Out,name+".png"),ImageFormat.Png);}
 public static void Asset(Bitmap b,string name){Save(b,name+"_native");using(Bitmap game=Scale(b,3))Save(game,name);using(Bitmap prev=Scale(b,4))Save(prev,name+"_4x");}
 public static Bitmap Ring(int frame){Bitmap b=New(64,64);int[] rr={22,23,24,25,24,23};int r=rr[frame];for(int y=0;y<64;y++)for(int x=0;x<64;x++){double d=Math.Sqrt((x-31.5)*(x-31.5)+(y-31.5)*(y-31.5));if(d>=r-3&&d<r+1){Color c=d>=r||d<r-2?Ink:(x+y<64?Light:Brass);b.SetPixel(x,y,c);}}return b;}
 public static Bitmap Arrow(int frame,int dir){Bitmap b=New(32,32);int[] bounce={0,1,2,3,2,1};int o=bounce[frame];Poly(b,Ink,15,3+o,25,14+o,20,14+o,20,26+o,11,26+o,11,14+o,6,14+o);Poly(b,Brass,15,5+o,22,13+o,18,13+o,18,24+o,13,24+o,13,13+o,9,13+o);Line(b,Light,1,15,7+o,11,12+o,14,12+o,14,22+o);if(dir==1)b.RotateFlip(RotateFlipType.Rotate90FlipNone);if(dir==2)b.RotateFlip(RotateFlipType.Rotate180FlipNone);if(dir==3)b.RotateFlip(RotateFlipType.Rotate270FlipNone);return b;}
 public static Bitmap Sheet(int w,int h,int count,Func<int,Bitmap> draw){Bitmap b=New(w*count,h);for(int i=0;i<count;i++)using(Bitmap f=draw(i))Paste(b,f,w*i,0);return b;}
 public static Bitmap Bubble(){Bitmap b=New(96,48);Poly(b,Ink,4,0,91,0,95,4,95,43,91,47,4,47,0,43,0,4);Rect(b,2,4,92,40,Rust);Rect(b,4,2,88,44,Rust);Rect(b,4,5,88,38,Paper);Rect(b,6,4,84,40,Paper);Line(b,Pale,1,7,6,88,6);Line(b,Rust,1,7,41,88,41);Rect(b,7,9,2,1,Pale);Rect(b,85,37,3,1,Rust);return b;}
 public static Bitmap Slice(Bitmap src,int w,int h){Bitmap b=New(w,h);int[] xs={0,8,88,96},ys={0,8,40,48};for(int yy=0;yy<3;yy++)for(int xx=0;xx<3;xx++){int dx=xx==0?0:xx==1?8:w-8,dy=yy==0?0:yy==1?8:h-8;int dw=xx==1?w-16:8,dh=yy==1?h-16:8;for(int y=0;y<dh;y++)for(int x=0;x<dw;x++)b.SetPixel(dx+x,dy+y,src.GetPixel(xs[xx]+x%(xs[xx+1]-xs[xx]),ys[yy]+y%(ys[yy+1]-ys[yy])));}return b;}
 public static Bitmap Tick(){Bitmap b=New(16,16);Poly(b,Ink,4,3,12,8,4,13);Poly(b,Light,5,5,10,8,5,11);return b;}
 static Dictionary<char,string> Font=new Dictionary<char,string>{{'0',"111101101101111"},{'1',"010110010010111"},{'2',"111001111100111"},{'3',"111001111001111"},{'4',"101101111001001"},{'5',"111100111001111"},{'6',"111100111101111"},{'7',"111001010010010"},{'8',"111101111101111"},{'9',"111101111001111"},{'A',"010101111101101"},{'D',"110101101101110"},{'E',"111100110100111"},{'S',"111100111001111"},{'H',"101101111101101"},{'I',"111010010010111"},{'F',"111100110100100"},{'T',"111010010010010"},{'B',"110101110101110"},{'/',"001001010100100"}};
 public static void Glyph(Bitmap b,string s,int cx,int cy){int x=cx-(s.Length*4-1)/2;foreach(char ch in s){string data=Font[ch];for(int y=0;y<5;y++)for(int col=0;col<3;col++)if(data[y*3+col]=='1')Rect(b,x+col,cy-2+y,1,1,Pale);x+=4;}}
 public static string[] Keys={"mouse_left","mouse_right","mouse_middle","mouse_wheel","shift","e","a","d","ad","1","2","3","4","5","6","7","8","9","0","tab"};
 public static Bitmap Chip(int size,int k){Bitmap b=New(size,size);int pad=(size-24)/2;Rect(b,1,3,size-2,size-6,Ink);Rect(b,3,1,size-6,size-2,Ink);Rect(b,3,3,size-6,size-6,Dark);Line(b,Brass,1,4,3,size-5,3);Line(b,Rust,1,4,size-4,size-5,size-4);int cx=size/2,cy=size/2;if(k<4){int x=cx-5,y=cy-7;Rect(b,x,y,10,15,Ink);Rect(b,x+1,y-1,8,17,Ink);Rect(b,x+1,y+1,8,13,Steel);Rect(b,cx,y,1,7,Ink);Rect(b,x+1,y+6,8,1,Ink);Rect(b,cx-1,y+2,3,4,Ink);if(k==0)Rect(b,x+1,y+1,3,5,Light);if(k==1)Rect(b,cx+1,y+1,3,5,Light);if(k==2)Rect(b,cx,y+2,1,4,Light);if(k==3){Rect(b,cx,y+2,1,4,Light);Poly(b,Light,cx+7,cy-6,cx+5,cy-3,cx+9,cy-3);Poly(b,Light,cx+7,cy+6,cx+5,cy+3,cx+9,cy+3);}}else{string s=Keys[k].ToUpper();if(s=="AD")s="A/D";Glyph(b,s,cx,cy);}return b;}
 public static Bitmap Chain(){Bitmap b=New(64,24);for(int i=0;i<6;i++){int x=3+i*9,y=6+(i%2)*3;Rect(b,x,y,13,7,Ink);Rect(b,x+1,y-1,11,9,Ink);Rect(b,x+2,y+1,9,5,Steel);Rect(b,x+4,y+2,5,3,Color.Transparent);Rect(b,x+2,y+1,8,1,Paper);}return b;}
 public static Bitmap Seal(bool done){Bitmap b=New(32,32);Poly(b,Ink,9,3,22,3,28,10,28,22,22,28,9,28,3,22,3,10);Poly(b,done?Green:Red,10,5,21,5,26,11,26,21,21,26,10,26,5,21,5,11);if(done){Line(b,Ink,5,9,15,14,20,23,10);Line(b,Pale,2,9,15,14,20,23,10);}else{Rect(b,10,13,12,10,Ink);Rect(b,12,15,8,6,Brass);Line(b,Ink,3,12,13,12,9,19,9,19,13);Rect(b,15,17,2,3,Ink);}return b;}
 public static void Text(Bitmap b,string s,int x,int y,int size,Color color){using(Graphics g=Graphics.FromImage(b))using(Font f=new Font("Malgun Gothic",size,FontStyle.Bold,GraphicsUnit.Pixel))using(Brush p=new SolidBrush(color)){g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.SingleBitPerPixelGridFit;g.DrawString(s,f,p,x,y);}}
 public static void Place(Bitmap b,string name,int x,int y){using(Bitmap a=new Bitmap(Path.Combine(Out,name+".png")))Paste(b,a,x,y);}
 public static void Mark(Bitmap b,int cx,int cy){using(Bitmap r=Ring(2))using(Bitmap s=Scale(r,3))Paste(b,s,cx-96,cy-96);using(Bitmap a=Arrow(0,2))using(Bitmap s=Scale(a,3))Paste(b,s,cx-48,cy-175);}
 public static void Instruction(Bitmap b,string s,string chip){Place(b,"officer_bust",54,864);using(Bitmap n=Bubble())using(Bitmap sl=Slice(n,300,48))using(Bitmap gs=Scale(sl,3))Paste(b,gs,204,864);Text(b,s,237,908,33,Ink);Place(b,"next_tick",1044,948);Text(b,"장교",70,830,27,Light);if(chip!=null){int k=Array.IndexOf(Keys,chip);using(Bitmap c=Chip(24,k))using(Bitmap cs=Scale(c,3))Paste(b,cs,1137,900);}}
 public static void Build(string root,string output){Out=output;Asset(Bubble(),"instruction_box");Asset(Tick(),"next_tick");Asset(Sheet(64,64,6,Ring),"highlight_ring");string[] dirs={"up","right","down","left"};for(int d=0;d<4;d++){int dir=d;Asset(Sheet(32,32,6,i=>Arrow(i,dir)),"pointer_"+dirs[d]);}Asset(Sheet(24,24,Keys.Length,i=>Chip(24,i)),"input_chips_24");Asset(Sheet(32,32,Keys.Length,i=>Chip(32,i)),"input_chips_32");Asset(Chain(),"locked_chain");Asset(Seal(false),"locked_seal");Asset(Seal(true),"complete_stamp");
 string src=Path.Combine(Out,"officer_bust_generated.png");using(Bitmap im=new Bitmap(src)){Rectangle bb=AlphaBounds(im);using(Bitmap b=New(48,48)){double scale=Math.Min(44.0/bb.Width,44.0/bb.Height);int w=(int)(bb.Width*scale),h=(int)(bb.Height*scale),ox=(48-w)/2,oy=46-h;for(int y=0;y<h;y++)for(int x=0;x<w;x++){Color c=im.GetPixel(bb.X+Math.Min(bb.Width-1,(int)(x/scale)),bb.Y+Math.Min(bb.Height-1,(int)(y/scale)));if(c.A>=128)b.SetPixel(ox+x,oy+y,Color.FromArgb(255,(c.R/17)*17,(c.G/17)*17,(c.B/17)*17));}Clean(b);Asset(b,"officer_bust");}}
 string[] names={"01_telescope","02_squad","03_magic","04_trap","05_repair","06_lens"};string[] lines={"오른쪽 버튼을 꾹 눌러 정찰하자.","분대를 골라 북쪽으로 보내자.","마법을 골라 들판에 사용하자.","함정을 직접 발동해 보자.","먼저 성벽을 수리하자.","망원경 렌즈를 사고 장착하자."};string[] labels={"전투 · 망원경","전투 · 분대 이동","전투 · 마법 사용","전투 · 함정 발동","정비 · 성벽 수리","정비 · 렌즈 구매·장착"};string[] chips={"mouse_right","shift","mouse_left","mouse_left","e","e"};Bitmap contact=New(1920*2,1080*3);
 for(int i=0;i<6;i++){using(Bitmap cap=new Bitmap(Path.Combine(root,"Docs/References/ui_redesign_v2/now_"+(i<4?"battle":"yard")+".png")))using(Bitmap b=New(1920,1080)){using(Graphics g=Graphics.FromImage(b))g.DrawImage(cap,new Rectangle(0,0,1920,1080));Rect(b,1230,144,660,96,Ink);Text(b,labels[i],1254,153,30,Light);Text(b,"합성 목업 · 기존 캡처 위 안내 배치",1254,195,24,Pale);if(i==0){Mark(b,1280,350);}if(i==1){Line(b,Light,3,265,580,610,580,610,820,265,820,265,580);Mark(b,740,480);Text(b,"북",720,455,33,Pale);Text(b,"Shift + 왼쪽 끌기 → 놓기 → 북 선택",300,200,30,Pale);}if(i==2){Mark(b,1230,440);Text(b,"마법 대상 위치 · 예시",1040,570,27,Pale);}if(i==3){Mark(b,1150,490);Text(b,"함정 발동 위치 · 예시",960,620,27,Pale);}if(i==4){Mark(b,430,500);Place(b,"locked_seal",1180,450);Place(b,"locked_chain",1130,560);}if(i==5){Mark(b,1740,490);Place(b,"complete_stamp",370,450);Text(b,"렌즈 구매 → 장착 확인 → 2단계 계단",1130,760,30,Pale);}Instruction(b,lines[i],chips[i]);Save(b,"mockup_"+names[i]);Paste(contact,b,(i%2)*1920,(i/2)*1080);}}
 Save(contact,"mockup_sheet_6steps");contact.Dispose();
 }
 public static Rectangle AlphaBounds(Bitmap b){int l=b.Width,t=b.Height,r=0,bo=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>=128){l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);bo=Math.Max(bo,y);}return Rectangle.FromLTRB(l,t,r+1,bo+1);}
 public static void Clean(Bitmap b){bool[,] seen=new bool[b.Width,b.Height];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(!seen[x,y]&&b.GetPixel(x,y).A>0){List<Point> c=new List<Point>();Queue<Point> q=new Queue<Point>();q.Enqueue(new Point(x,y));seen[x,y]=true;while(q.Count>0){Point p=q.Dequeue();c.Add(p);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=p.X+dx,yy=p.Y+dy;if(xx>=0&&yy>=0&&xx<b.Width&&yy<b.Height&&!seen[xx,yy]&&b.GetPixel(xx,yy).A>0){seen[xx,yy]=true;q.Enqueue(new Point(xx,yy));}}}if(c.Count<4)foreach(Point p in c)b.SetPixel(p.X,p.Y,Color.Transparent);}}
}
'@
Add-Type -TypeDefinition $code -ReferencedAssemblies System.Drawing
[TutorialArt]::Build($root,$out)
